from batch2_author import make
make('DOC022',[
(1,'提高日常软件开发效率。','explicit','direct',[63,69,75],['工具依场景选择；不是要求所有开发者统一使用Vim。'],'本人明确说开发者追求效率并据效率选工具，且已开始学习VS Code。',[]),
(2,'在不同设备和仅有终端的服务器上都能开始工作及修改代码。','explicit','direct',[15,21,87],['本人所述服务器场景没有图形界面；并非验证所有服务器都如此。'],'反复说明在任何设备开始工作是其心态，并以服务器终端修改为选用Vim的重要用途。',[]),
(3,'保持编辑工具轻量并能快速打开。','inferred','inferred',[15,27],['本人偏重启动速度和较少资源消耗；关于各产品RAM/CPU表现是主观比较，未测量。'],'选择工具时反复强调轻和快的价值，支持维持性能特性的推断；不把描述转为量化性能保证。',['假定其以该特性作为主要选择理由反映继续需要。']),
(4,'按个人工作流定制本地编辑器的插件、外观、快捷键和语法表现。','explicit','direct',[15,31,35],['本地定制；配置文件方式为所选工作流，主题酷只是个人偏好。'],'本人直接说会安装插件、定制界面和快捷键以符合个人体验。',[]),
(5,'让个人编辑配置便于带到其他设备并保持熟悉的环境。','inferred','inferred',[31,69],['可通过复制配置或账户设置等；不要求仅使用配置文件；本人认为维护Vim配置有麻烦。'],'本人说明保存配置可复制熟悉环境，并称跨设备账户设置更容易，支持便携一致意图。',['假定其重视可移植性和一致性而不执著单一同步实现。']),
(6,'继续尽量只用键盘完成编辑和切换操作，以提高效率。','explicit','direct',[55,63],['个人操作偏好；不用鼠标非所有任务不可让步规则；早期酷感重要性已降低。'],'明确表示会继续使用且双手留键盘提高效率，保留维持意图和偏好。',[]),
(7,'在大型项目中快速按文件名定位并打开所需文件。','explicit','direct',[33,41,51],['利用模糊搜索与自定义快捷键；个人键位例子不强制为所有用户默认。'],'本人明确说插件目标是搜索文件，并举大量日志需定位的用途，选定模糊搜索方式保留。',[]),
(8,'能够跨项目文件搜索字符串并定位需要的内容。','explicit','direct',[41,51],['本人描述的跨文件搜索用法；对模糊算法机制的解释未验证。'],'本人明确把跨文件字符串搜索作为可执行目的和常用定位动作。',[]),
(9,'继续方便地查看文件结构并切换已打开的文件。','inferred','inferred',[33,51],['通过文件树、缓冲区和快捷键的当前工作流；快捷键不必为全产品硬编码。'],'反复使用并为多文件管理解释用途，支持维持文件导航能力的推断。',['假定所述典型工作流的便捷导航用途会继续需要。']),
(10,'在终端内快速切换代码编辑与执行结果查看，发现错误后返回修改。','inferred','inferred',[51,65],['当前用Tmux分窗结合Vim；不要求删除其他工具。'],'典型工作流直接说明切窗、立即看结果及返回改错，支持维持短反馈循环的意图推断。',['假定其满意的开发流程旨在继续保持该效率。']),
(11,'设备意外关闭后能较快恢复此前终端工作会话。','inferred','inferred',[51],['本人报告通过保存Tmux过程恢复；未核验具体插件或恢复完整性。'],'解释保存过程的明确目的为关机后恢复，支持维持该结果的推断；不声称可恢复未保存代码。',['假定其特意保存会话意味着希望保有恢复能力。']),
(12,'降低熟悉编辑器和编写配置的学习负担。','inferred','inferred',[55,61,65,69],['早期曲线陡，现可借社区、视频和AI辅助；本人会接受逐渐形成肌肉记忆。'],'配置语言困难、耗时维护及对更容易方式的肯定支持降低负担，不推导零学习或必须依赖AI。',['假定被明确比较为困难的学习配置环节有改善意图。']),
(13,'在使用VS Code时沿用熟悉的Vim操作方式和快捷键。','explicit','direct',[69,75],['服务器上仍可用Vim；VS Code通过相应插件整合是本人理解。'],'本人直接说可使用相同快捷键开发并结合两种工具优点，保留相容方式。',[]),
(14,'便于在同一编辑环境衔接开发、测试、代码审查、部署和监控。','inferred','inferred',[69,81,87,91],['本人正逐渐熟悉集成方式；扩展能力为其报告而非本次验证；并非要求全部场景禁止浏览器。'],'称集中流水线有帮助并据此学习VS Code提高效率，支持集成目的；不把演示的每一云产品都列为强制整合。',['假定其正面比较并主动学习反映希望减少跨工具衔接。']),
(15,'便于利用AI代码建议及所选代码、文件上下文辅助修改。','inferred','inferred',[33,69],['当前能力描述；AI建议不保证正确，不将其当自动执行授权。'],'本人积极比较AI建议、选择代码和文件进行修改的便利，支持维持这种辅助用途的推断。',['假定其特别重视并举例的辅助能力是期望继续利用。']),
(16,'编辑器必须支持插件或扩展，以适配开发需要。','explicit','direct',[103],['本人对开发编辑器的要求；不是每项功能都须内置。'],'明确说must supports plugins or extensions，不因功能已存在而过滤其不可或缺意图。',[]),
(17,'选用有活跃使用者和开发者社区的编辑器，以便解决问题并看到持续改进。','explicit','direct',[103,109],['社区可在Stack Overflow、Reddit、YouTube等出现；平台不是关键，规模和讨论活跃是价值。'],'本人明确强调社区重要并解释问题解决与持续改进，保留社区用途而不强定指定网站。',[]),
(18,'能方便地发现、了解并安装合适的编辑扩展。','inferred','inferred',[93,97],['看文档、讨论、评分及展示；市场式安装是其正面例子，未要求每项市场信息都必填。'],'比较扩展市场集中了解安装与分散找配置代码的成本，支持方便选择安装的意图推断。',['假定正面比较表明重视发现和安装的便利。']),
(19,'根据当前场景选择合适工具，并熟悉多种方式而非固守单一编辑器。','explicit','direct',[75,87],['仍喜欢终端；前端等场景可用其他工具；不是要求全部人同时掌握所有编辑器。'],'本人直接说不需stick to single tool并希望两种方式都可用，保留情境化偏好。',[]),
(20,'编辑代码时能利用适合语言的缩进和语法高亮来理解代码结构。','explicit','direct',[9,11],['开发编辑器一般性期望；具体语言作为例子，不推定对每种语言的完整支持范围。'],'本人以has to解释语言定制需求，并直接说明高亮使代码更易读；不把语言机制解释当已验证技术事实。',[])
],
'覆盖T000—T117，长段T050—T075另行完整回读以补齐显示截断。此处codespace是受访者泛指代码编辑环境，未擅定为GitHub Codespaces。Vim转写中的多种拼法按上下文理解，未改动源文。',
'多根保留可移植、编辑效率、学习、生态和场景取舍。F1考虑G5配置便携与G13熟悉键位共同实现G2跨设备工作，但实际工具安装、环境权限和仅终端场景仍未知，proposed/partial。G7/G8分别是文件和内容定位，不能因为共享模糊搜索就看成同一目标。G10开发循环与G14全流水线整合的范围不同，不把先后操作当精化。G16插件与G17社区都是本人明确重要要求，不能仅作为无目标事实过滤；两者并非共同足以满足所有开发需求。酷感是历史动机及仍有的次要偏好，不强设新产品炫酷根。',
'正常（分析假设）：到无图形界面的服务器，凭Vim基础操作改文件，检验G2/G6；若本地VS Code使用熟悉键位，也仅覆盖另一场景。异常（分析假设）：配置可复制但服务器缺少依赖或无安装权限，F1不足以确保可工作。异常（分析假设）：机器关闭后会话能恢复但未保存代码丢失，G11没有涵盖数据零丢失保证。异常（分析假设）：社区规模大但具体问题尚无答案，G17要求良好支持环境而非每问必答。能集成流水线也不自动保证部署正确或AI建议安全。',
questions=[([2,5,13],'跨设备工作的最低环境、配置同步和键位一致性范围是什么？','可移植配置不足以保证所有设备可工作；受访者关于可用性的说法未验证。'),([11],'希望恢复哪些会话状态，如何区分未保存内容？','当前只描述保存过程，没有恢复保证范围。'),([14],'哪些流水线阶段和系统是必需整合，哪些只是示例？','整段含较多产品能力报告，不能全部升格为承诺。'),([17,18],'社区支持及扩展发现达到何种程度算足够？','未给规模、时效或可靠性验收标准。')],
groups=[dict(group_id='DOC022-F1',parent_id=2,child_ids=[5,13],kind='and',status='proposed',completeness='partial',rationale='携带配置和熟悉键位帮助跨设备工作，但不能保证目标环境可运行工具、安装依赖或提供权限，尤其仅终端服务器情境仍有缺口。',assumptions=['只考虑操作习惯迁移，不预设每台设备均有相同运行环境。'],evidence=[15,31,69,75,87])])
